import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Element;
import org.jsoup.safety.Safelist;
import org.junit.Test;

import static org.junit.Assert.*;

public class SafelistTest {

    @Test
    public void noneTest() {
        final Safelist safelist = Safelist.none();
        assertNotNull(safelist);
    }

    @Test
    public void simpleTextTest() {
        final Safelist safelist = Safelist.simpleText();
        assertNotNull(safelist);
    }

    @Test
    public void basicTest() {
        final Safelist basicSafelist = Safelist.basic();
        assertNotNull(basicSafelist);
    }

    @Test
    public void basicWithImagesTest() {
        final Safelist safelist = Safelist.basicWithImages();
        assertNotNull(safelist);
    }

    @Test
    public void relaxedTest() {
        final Safelist safelist = Safelist.relaxed();
        assertNotNull(safelist);
    }

    @Test
    public void copySafelistTest() {
        final Safelist safelist1 = Safelist.basic();
        final Safelist safelist2 = new Safelist(safelist1);
        assertNotNull(safelist2);
    }

    @Test
    public void addTagsTest() {
        final Safelist safelist = new Safelist();
        safelist.addTags("a", "b");
        assertTrue(safelist.isSafeTag("a"));
        assertTrue(safelist.isSafeTag("b"));
    }

    @Test
    public void removeTagsTest() {
        final Safelist safelist = new Safelist();
        safelist.addTags("a", "b");
        safelist.removeTags("b");
        assertTrue(safelist.isSafeTag("a"));
        assertFalse(safelist.isSafeTag("b"));
    }

    @Test
    public void addAttributesTest() {
        final Safelist safelist = new Safelist();
        safelist.addAttributes("a", "href");
        assertTrue(safelist.isSafeAttribute("a", new Element("a"), new Attribute("href", "")));
    }

    @Test
    public void removeAttributesTest() {
        final Safelist safelist = new Safelist();
        safelist.addAttributes("a", "href");
        safelist.removeAttributes("a", "href");
        assertFalse(safelist.isSafeAttribute("a", new Element("a"), new Attribute("href", "")));
    }

    @Test
    public void addEnforcedAttributeTest() {
        final Safelist safelist = new Safelist();
        safelist.addEnforcedAttribute("a", "target", "_blank");
        assertNotNull(safelist.getEnforcedAttributes("a"));
    }

    @Test
    public void removeEnforcedAttributeTest() {
        final Safelist safelist = new Safelist();
        safelist.addEnforcedAttribute("a", "target", "_blank");
        safelist.removeEnforcedAttribute("a", "target");
        assertTrue(safelist.getEnforcedAttributes("a").isEmpty());
    }

    @Test
    public void preserveRelativeLinksTest() {
        final Safelist safelist = new Safelist();
        safelist.preserveRelativeLinks(true);
        assertTrue(safelist.preserveRelativeLinks(false));
    }

    @Test
    public void addProtocolsTest() {
        final Safelist safelist = new Safelist();
        safelist.addProtocols("a", "href", "http", "https");
        // No assertions possible as addProtocols doesn't allow to verify addition
    }

    @Test
    public void removeProtocolsTest() {
        final Safelist safelist = new Safelist();
        safelist.addProtocols("a", "href", "http", "https");
        safelist.removeProtocols("a", "href", "https");
        // No assertions possible as removeProtocols doesn't allow to verify removal
    }
}
